insert into weeks (week_start, era, theme, content) values ('2026-10-15', '先秦', '诗经 · 风雅之始', $json${"intro":"**欢迎来到一日一诗。**从今天起，每天清晨六点，你会收到一首诗、一个你可能还不熟悉的成语。我们会从三千年前的河边出发，一路读到明清。\n\n第一站是《诗经》。它是中国最早的诗歌总集，收了西周初年到春秋中期大约五百年间的三百零五篇诗，分成「风」「雅」「颂」三类。「风」是各地的民歌，「雅」是朝廷宴会的乐歌，「颂」是祭祀用的颂歌。接下来十二天，我们读的大多是「风」：普通人的恋爱、婚嫁、战争、劳作、抱怨和思乡。\n\n读的时候留意两件事。一是**兴**：先写眼前的鸟、草、树，再引出心里的话。二是**重章叠句**：同一段话换几个字反复唱。它们原本都是配乐唱的歌，所以读出声来最有味道。\n\n这十二首诗排成了一条线：从相思，到婚嫁，到离别与战争，再到劳作、愤怒与故国之思。读完，你会看到三千年前的人，和我们其实没有那么不同。","preview":["10/15 周四　关雎 · 寤寐思服","10/16 周五　蒹葭 · 秋水伊人","10/17 周六　静女 · 搔首踟蹰","10/18 周日　子衿 · 风雨如晦","10/19 周一　木瓜 · 投木报琼","10/20 周二　桃夭 · 宜室宜家","10/21 周三　击鼓 · 死生契阔","10/22 周四　氓 · 二三其德","10/23 周五　伐檀 · 尸位素餐","10/24 周六　硕鼠 · 爰得我所","10/25 周日　黍离 · 黍离之悲","10/26 周一　采薇 · 雨雪霏霏"]}$json$::jsonb)
on conflict (week_start) do update set era = excluded.era, theme = excluded.theme, content = excluded.content, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-15', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安。**关关{雎鸠|jū jiū}，在河之洲。三千年前的鸟已经叫了，你也该起床了。","chengyu":{"word":"寤寐思服","pinyin":"wù mèi sī fú","meaning":"醒着想，睡着也想，形容日日夜夜都在思念。{寤|wù}是醒，{寐|mèi}是睡，「思」和「服」都是想念。","examples":["出国交换半年，我最寤寐思服的不是家，是我妈煮的那锅汤。","那双限量球鞋我寤寐思服了一整年，今天终于抢到了！"],"note":"语气偏书面，正经地用很典雅，用来调侃日常小事也很有趣。它思念的是人或物，不能用来说「反复思考一个问题」。","origin":"出自今天的诗《关雎》。紧接着的下一句，就是你早就熟悉的「辗转反侧」。原来这两个成语是一对，前一句说想念，后一句说想得睡不着。"},"poem":{"title":"关雎","source":"《诗经 · 周南》","image":"/poems/guanju.png","lines":["关关雎鸠，在河之洲。窈窕淑女，君子好逑。","参差荇菜，左右流之。窈窕淑女，寤寐求之。","求之不得，寤寐思服。悠哉悠哉，辗转反侧。","参差荇菜，左右采之。窈窕淑女，琴瑟友之。","参差荇菜，左右{芼|mào}之。窈窕淑女，钟鼓{乐|lè}之。"],"summary":"河边的水鸟一声声和鸣，引出一个青年对姑娘的思慕。他想她想得睡不着，又幻想着弹琴鼓瑟去亲近她，最后敲钟打鼓迎娶她。全诗从相思写到成婚，感情热烈，却始终有分寸。","notes":[{"term":"关关","gloss":"雎鸠的叫声，是拟声词。"},{"term":"{窈窕|yǎo tiǎo}","gloss":"幽静美好的样子。"},{"term":"{好逑|hǎo qiú}","gloss":"好的配偶。「逑」就是配偶。"},{"term":"{参差|cēn cī}{荇菜|xìng cài}","gloss":"长短不齐的荇菜，一种可以吃的水草。"},{"term":"流之","gloss":"顺着水流去捞取。后面的「采之」「芼之」也都是采摘的意思。"},{"term":"琴瑟友之、钟鼓乐之","gloss":"用琴瑟去亲近她，用钟鼓让她快乐。诗到这里，已经从追求写到了迎娶。"}],"technique":"诗以水鸟和鸣开篇，借眼前的景物引出要说的情感，这叫「**兴**」，是《诗经》最典型的手法。三次写采荇菜，每次只换一个动词（流、采、芼），这种「**重章叠句**」让感情一层层推进。这两个术语写华文赏析题时都用得上。","history":{"title":"一首情歌，怎么成了道德课本？","body":"《诗经》是中国最早的诗歌总集，收录了西周初年到春秋中期的三百零五篇诗，《关雎》排在第一篇。孔子评价它「乐而不{淫|yín}，哀而不伤」：快乐却不放纵，忧伤却不过度。\n\n到了汉代，汉武帝独尊儒术，《诗经》被列为五经之一，成了官方经典。当时解诗的《毛诗序》说《关雎》歌颂的是「后妃之德」，把一首民间情歌读成了宫廷道德教材。直到宋代以后，才陆续有学者主张回到诗句本身，把它当作爱情诗来读。\n\n所以《关雎》能排在三百篇之首，不只是因为写得好，也因为两千年来每个时代都在借它说自己想说的话。"}},"appreciation":{"type":"字词流变","title":"「窈窕」的变身","body":"今天的减肥广告爱说「窈窕身材」，意思是苗条。可在《关雎》里，「窈窕」原本形容的是幽静美好的样子。古人注释还有「善心为窈，善容为窕」的说法，一半说内在，一半说仪态，跟腰围没什么关系。\n\n三千年下来，一个词从「心灵美」变成了「瘦」。下次看到这类广告，你可以默默纠正一下。"},"signoff":"**明天见。**今晚，希望你不必寤寐思服，一觉睡到天亮。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-16', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安。**昨天学的是「寤寐思服」，日夜想念。今天想念的那个人，还站在水的另一边。","chengyu":{"word":"秋水伊人","pinyin":"qiū shuǐ yī rén","meaning":"秋天的水边，有一位思念的人。用来指心中想念、却难以接近的人，也形容那份怅惘的思念。","examples":["翻到毕业照，大家早已各奔东西，突然有点秋水伊人的感觉。","他常常提起中学时那位学姐，说得像秋水伊人一样，可望而不可即。"],"note":"带点文艺和惆怅，适合写想念远方的人或回忆。用在日常聊天里会显得很有书卷气，也可以拿来自嘲。","origin":"化用今天的诗《蒹葭》。诗里写深秋的芦苇、白露、河水，和「在水一方」的「伊人」，后人便用「秋水伊人」概括这份思念。"},"poem":{"title":"蒹葭","source":"《诗经 · 秦风》","lines":["蒹葭苍苍，白露为霜。所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。","蒹葭萋萋，白露未{晞|xī}。所谓伊人，在水之{湄|méi}。溯洄从之，道阻且{跻|jī}。溯游从之，宛在水中{坻|chí}。","蒹葭采采，白露未已。所谓伊人，在水之{涘|sì}。溯洄从之，道阻且右。溯游从之，宛在水中{沚|zhǐ}。"],"summary":"深秋清晨，芦苇茫茫，露水结成了霜。诗人想念的那个人，就在河的另一边。他逆着水流去找，路又险又长；顺着水流去找，那人又仿佛站在水中央。看得见，却总是到不了。","notes":[{"term":"{蒹葭|jiān jiā}","gloss":"芦苇。"},{"term":"苍苍、萋萋、采采","gloss":"都是茂盛的样子，三章换字不换意。"},{"term":"伊人","gloss":"那个人，指诗人思念的对象。"},{"term":"{溯洄|sù huí}","gloss":"逆流而上。「溯游」则是顺流而下。"},{"term":"未晞、未已","gloss":"露水还没干、还没停。时间从清晨推到日出，诗人一直在找。"},{"term":"湄、涘","gloss":"都是水边、岸边。"},{"term":"坻、沚","gloss":"都是水中的小洲。"}],"technique":"这首诗最迷人的地方是「**可望而不可即**」：伊人是谁、在哪，始终说不清。王国维在《人间词话》里说，《蒹葭》最得「风人深致」，就是指这种含蓄悠远的韵味。写作文要表达追求理想却遥不可及，这首诗是很好的引用。","history":{"title":"最会打仗的秦国，写出最朦胧的诗","body":"《秦风》来自秦国。秦人原本是西部边陲替周王养马的部族，直到公元前770年周平王东迁，秦襄公护送有功，才被封为诸侯。\n\n秦地民风尚武，《秦风》里也有「岂曰无衣，与子同袍」这样慷慨的战歌。可偏偏是这片土地，留下了《诗经》里最朦胧、最温柔的一首。\n\n五百多年后，秦国统一天下。读《蒹葭》的时候不妨想一想：再强硬的民族，也有站在河边发呆的时刻。"},"image":"/poems/jianjia.png"},"appreciation":{"type":"文学回响","title":"从《蒹葭》到《在水一方》","body":"一九七五年，琼瑶写了小说《在水一方》，书名就来自这首诗。后来改编成歌，由邓丽君演唱，「在水一方」四个字从此走进了流行文化。\n\n三千年前河边的一声叹息，被七十年代的台湾作家接住，又被一代代华人传唱。好诗就是这样，换个时代，换种唱法，照样动人。"},"signoff":"**明天见。**愿你心里的「伊人」，不论是人还是梦想，都终有一天走得到。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-17', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安。**所谓伊人，在水一方。今天这位姑娘可不在水边，她就躲在城墙角落，等你出现。","chengyu":{"word":"搔首踟蹰","pinyin":"sāo shǒu chí chú","meaning":"挠着头，在原地走来走去。形容心里焦急、犹豫不决，不知道怎么办才好。","examples":["约好的人迟迟不来，他在门口搔首踟蹰了半个小时。","站在奶茶店前搔首踟蹰了十分钟，最后还是点了平常那杯。"],"note":"画面感很强，适合写等待、犹豫的样子。用在小事上自嘲，效果特别好。","origin":"出自今天的诗《静女》：「爱而不见，搔首踟蹰。」约会的男孩找不到姑娘，急得挠头打转。"},"poem":{"title":"静女","source":"《诗经 · 邶风》","lines":["静女其{姝|shū}，{俟|sì}我于城隅。爱而不见，搔首踟蹰。","静女其{娈|luán}，{贻|yí}我{彤管|tóng guǎn}。彤管有{炜|wěi}，{说怿|yuè yì}女美。","自牧归{荑|tí}，{洵|xún}美且异。匪女之为美，美人之贻。"],"summary":"一位文静美丽的姑娘，约男孩在城墙角见面，却故意躲起来，急得他团团转。后来她送了他一支红色的「彤管」，又从郊外带回一把嫩茅草。他捧着这些小东西，觉得美得不得了。其实不是东西美，而是因为送的人美。","notes":[{"term":"静女","gloss":"文静娴雅的姑娘。"},{"term":"城隅","gloss":"城墙的角落，约会的地点。"},{"term":"爱而不见","gloss":"「爱」通「薆」，隐藏。姑娘故意躲着不出来。"},{"term":"说怿女美","gloss":"「说」通「悦」，「女」通「汝」。我喜爱你的美。"},{"term":"自牧归荑","gloss":"从郊外带回一把茅草嫩芽。「归」通「馈」，赠送。"},{"term":"匪女之为美","gloss":"「匪」通「非」。不是你（茅草）本身美，而是美人送的才美。"}],"history":{"title":"邶、鄘、卫：三个名字，一个国家","body":"《诗经》里有《邶风》《鄘风》《卫风》三组诗，其实都来自同一片土地：商朝旧都朝歌一带。\n\n周武王灭商后，把这里分成邶、鄘、卫三块，派人看管，史称「三监」。后来三监作乱，周公东征平定，邶和鄘都并入卫国。所以这三组诗，读起来都带着卫国的味道。\n\n曾经的商朝都城，到了周代，留下的是这首俏皮的约会小诗。"},"image":"/poems/jingnv.png"},"appreciation":{"type":"名物小识","title":"「彤管」到底是什么？","body":"两千多年来，学者一直在吵：「彤管」到底是什么？\n\n有人说是红色的笔杆，是女史记事用的；有人说是一种红色的管状乐器；也有人认为，它就是下一章的「荑」，一根红润的茅草嫩芽。\n\n没有标准答案。可也许答案根本不重要，就像诗里说的：东西是什么不要紧，要紧的是谁送的。"},"signoff":"**周末愉快。**希望你今天不必搔首踟蹰，想见的人都准时出现。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-18', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安，周日。**今天如果有人约你，别搔首踟蹰太久，直接去吧。","chengyu":{"word":"风雨如晦","pinyin":"fēng yǔ rú huì","meaning":"风雨交加，天色昏暗得像黑夜。后来多用来比喻局势黑暗、社会动荡。","examples":["期末考那个月真是风雨如晦，好在大家一起熬过来了。","公司风雨如晦的那几年，是她一直撑着整个团队。"],"note":"{晦|huì}是昏暗。正式场合用来写时局；日常里用来夸张形容一段很难熬的日子，也很传神。常和下一句「鸡鸣不已」一起用，表示在黑暗中依然坚守。","origin":"出自《郑风 · 风雨》：「风雨如晦，鸡鸣不已。既见君子，云胡不喜。」它和今天的《子衿》同在《郑风》，写的也是等一个人的心情：外面风雨交加，见到你，怎能不欢喜。"},"poem":{"title":"子衿","source":"《诗经 · 郑风》","lines":["青青子{衿|jīn}，悠悠我心。纵我不往，子宁不{嗣|sì}音？","青青子佩，悠悠我思。纵我不往，子宁不来？","挑兮达兮，在城{阙|què}兮。一日不见，如三月兮。"],"summary":"一个姑娘在城楼上等她的心上人。她想：就算我没去找你，你难道就不能捎个信吗？就算我没去，你难道就不能来吗？她在城楼上走来走去，一天不见，像过了三个月。","notes":[{"term":"子衿","gloss":"你的衣领。「青衿」是当时读书人的服装，借衣领代指那个人。"},{"term":"悠悠","gloss":"绵长不断的样子，形容思念。"},{"term":"嗣音","gloss":"寄来音信。"},{"term":"子佩","gloss":"你佩玉的绶带。"},{"term":"{挑|tāo}兮达兮","gloss":"来来回回走动的样子。"},{"term":"城阙","gloss":"城门两边的观楼。"}],"technique":"全诗不写对方长什么样，只写一领衣襟、一条佩带，再写自己等得坐立不安。用**细节和动作**写思念，比直接说「我很想你」高明得多。","history":{"title":"孔子为什么说「郑声淫」？","body":"郑国位于中原交通要道，商业发达，民风开放，《郑风》里有大量恋爱诗，而且常常是女子主动表白，《子衿》就是一例。\n\n孔子在《论语》里说「郑声淫」，主张「放郑声」。不过学者多认为，他批评的主要是郑国的音乐过于放纵，而不是这些诗。毕竟，《郑风》还是被收进了《诗经》，一首没少。\n\n一个说要远离郑声的人，却让郑国的情歌流传了两千多年，这本身就很有意思。"},"image":"/poems/zijin.png"},"appreciation":{"type":"人物回响","title":"曹操也在等一个人","body":"八百多年后，曹操写《短歌行》，直接借用了这首诗的开头：「青青子衿，悠悠我心。」\n\n只是他等的不是恋人，而是人才。原诗的相思，被他改写成了求贤若渴。\n\n后来，「青衿」也渐渐成了读书人、学子的代称。三千年前一个姑娘望着的那件青色衣领，今天就穿在你我身上。"},"signoff":"**周末愉快。**一日不见，如三月兮。我们明天见。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-19', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安，新的一周。**青青子衿，悠悠我心。今天我们把想念，换成一份礼物。","chengyu":{"word":"投木报琼","pinyin":"tóu mù bào qióng","meaning":"别人送我木瓜，我回赠美玉。比喻得到别人的一点好意，就用更重的情谊回报。","examples":["我只是帮她带了一杯奶茶，她居然送我整整一本笔记，真是投木报琼。","你上次在我最难的时候陪我，这份情，我一定投木报琼。"],"note":"可以用来感谢对方「回报远超我的付出」，也可以表示自己要厚报。重点不在东西值多少钱，而在情谊。","origin":"出自今天的诗《木瓜》：「投我以木瓜，报之以琼琚。」"},"poem":{"title":"木瓜","source":"《诗经 · 卫风》","lines":["投我以木瓜，报之以{琼琚|qióng jū}。匪报也，永以为好也！","投我以木桃，报之以琼瑶。匪报也，永以为好也！","投我以木李，报之以琼{玖|jiǔ}。匪报也，永以为好也！"],"summary":"你送我木瓜、木桃、木李，我回赠你琼琚、琼瑶、琼玖这样的美玉。可这不是为了还礼，而是希望我们永远相好。","notes":[{"term":"投","gloss":"投赠，送给。"},{"term":"琼琚、琼瑶、琼玖","gloss":"都是美玉。「琼」是美玉的统称。"},{"term":"匪报也","gloss":"「匪」通「非」。不是为了回报。"},{"term":"永以为好","gloss":"永远相好。全诗的重点就在这一句。"}],"history":{"title":"礼尚往来：周代人怎样送礼","body":"周代是一个讲「礼」的社会。《礼记》里说：「礼尚往来，往而不来，非礼也；来而不往，亦非礼也。」送礼、还礼，是维系人际关系的规矩。\n\n玉在周代地位特别高。古人认为玉温润坚韧，象征君子的品德，所以有「君子比德于玉」的说法。用美玉回报木瓜，是把最珍贵的东西，交给最在乎的人。\n\n《木瓜》的有趣之处在于，它看似在说礼尚往来，最后却一句话推翻了交换的逻辑：匪报也。"},"image":"/poems/mugua.png"},"appreciation":{"type":"今日回响","title":"送礼，到底在送什么？","body":"过年时，我们常常默默计算红包的数目，生日礼物也会不自觉地比较价钱。送礼好像变成了一道算术题。\n\n《木瓜》提醒我们：礼物不是交易。木瓜换美玉，从价钱上看一点都不对等，可诗人根本不在乎，他要的只是「永以为好」。\n\n下次收到朋友的一份小心意，不妨想想这首诗。"},"signoff":"**明天见。**如果今天有人对你好，记得投木报琼。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-20', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安。**桃之夭夭，灼灼其华。愿你今天也开得热热闹闹。","chengyu":{"word":"宜室宜家","pinyin":"yí shì yí jiā","meaning":"使家庭和顺美满。原指女子出嫁后，能让夫家和睦；现在多用来形容家庭和睦、适合成家的样子。","examples":["新房布置得温暖又舒服，一看就宜室宜家。","他们两个性格互补，一个爱煮饭一个爱打扫，真是宜室宜家。"],"note":"原句带有古代对女性角色的期待。今天使用时，可以用来形容一个家、一对伴侣，而不只用来评价女性。","origin":"出自今天的诗《桃夭》：「之子于归，宜其室家。」"},"poem":{"title":"桃夭","source":"《诗经 · 周南》","lines":["桃之{夭夭|yāo yāo}，{灼灼|zhuó zhuó}其华。之子于归，宜其室家。","桃之夭夭，有{蕡|fén}其实。之子于归，宜其家室。","桃之夭夭，其叶{蓁蓁|zhēn zhēn}。之子于归，宜其家人。"],"summary":"桃树长得茂盛，花开得鲜艳；这个姑娘出嫁了，会让她的家和和美美。诗从花写到果，再写到叶，祝福一层比一层深：愿她如花般美丽，像果实一样多子多福，像枝叶一样让一家人兴旺。","notes":[{"term":"夭夭","gloss":"桃树茂盛美丽的样子。"},{"term":"灼灼","gloss":"花开得鲜艳明亮，像火一样。"},{"term":"华","gloss":"通「花」。"},{"term":"之子于归","gloss":"这个姑娘出嫁了。「于归」指女子出嫁。"},{"term":"有蕡其实","gloss":"果实又多又大。"},{"term":"蓁蓁","gloss":"叶子茂密的样子。"}],"technique":"「**花 → 果 → 叶**」的顺序很巧：从眼前的美，写到将来的收获，再写到长久的繁盛。三章只换几个字，祝福却层层递进，这就是《诗经》典型的重章叠句。","history":{"title":"为什么在春天结婚？","body":"《周礼》记载，掌管婚姻的官员叫「媒氏」，每到仲春二月，就会让适婚的男女相会，这时结婚不必拘泥繁琐的礼节。\n\n春天桃花盛开，万物生长，古人相信人间的婚配应当和天地的节律同步。所以《桃夭》用桃花起兴，不只是因为好看，更因为桃花开的季节，正是婚嫁的季节。\n\n一首两千多年前的婚礼祝歌，背后是周人对季节、生命和家庭的整套理解。"},"image":"/poems/taoyao.png"},"appreciation":{"type":"婚俗小识","title":"喜帖上的「之子于归」","body":"如果你参加过华人婚礼，可能在喜帖、红布或对联上见过四个字：「之子于归」。这正是从《桃夭》来的，三千年后仍然是婚礼上的吉祥话。\n\n有意思的是「归」字。古人认为女子出嫁才是真正「回到」了归宿，所以出嫁叫「于归」。今天看来，这个说法带着时代的印记，但这四个字承载的祝福依然温暖。"},"signoff":"**明天见。**愿你像那株桃树一样，灼灼其华。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-21', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安。**昨天的「宜室宜家」太甜，今天的诗，要从战鼓声开始。","chengyu":{"word":"死生契阔","pinyin":"sǐ shēng qì kuò","meaning":"无论生死、聚散，都不分离。「契」是聚合，「阔」是分离。形容誓同生死、患难与共的情谊。","examples":["他们从小学就认识，一路死生契阔，到现在还是最好的朋友。","毕业以后天各一方，聚少离多，才真正懂了什么叫死生契阔。"],"note":"很多人把这句当作浪漫的婚礼誓词，但原诗写的是一名被困战场的士兵，而且誓言最终落空了。用的时候知道这层悲凉，会更有分量。","origin":"出自今天的诗《击鼓》：「死生契阔，与子成说。执子之手，与子偕老。」"},"poem":{"title":"击鼓","source":"《诗经 · 邶风》","lines":["击鼓其{镗|tāng}，踊跃用兵。土国城{漕|cáo}，我独南行。","从孙子仲，平陈与宋。不我以归，忧心有{忡|chōng}。","{爰|yuán}居爰处？爰丧其马？于以求之？于林之下。","死生{契阔|qì kuò}，与子成说。执子之手，与子偕老。","{于嗟|xū jiē}阔兮，不我活兮。于嗟{洵|xún}兮，不我{信|shēn}兮。"],"summary":"战鼓咚咚，别人在国内修土木、筑城墙，只有我被派往南方打仗。跟着将军孙子仲出征，迟迟不让回家。马跑丢了，人也恍惚。他想起出征前和她立下的誓言：同生共死，牵着手一起变老。可如今离得太远，誓言再也无法兑现。","notes":[{"term":"镗","gloss":"鼓声。"},{"term":"土国城漕","gloss":"在国内修土工，在漕邑筑城。"},{"term":"平陈与宋","gloss":"联合陈国、宋国。"},{"term":"不我以归","gloss":"不让我回家。"},{"term":"爰","gloss":"于是、在哪里。"},{"term":"成说","gloss":"立下约定。"},{"term":"于嗟","gloss":"叹词，唉。"},{"term":"洵","gloss":"远。"},{"term":"信","gloss":"通「伸」，守约、实现诺言。"}],"technique":"最动人的誓言放在第四章，第五章紧接着就是两声叹息。**先给希望，再亲手打碎**，这个结构让「执子之手，与子偕老」读起来格外心酸。","history":{"title":"一场谁也不想打的仗","body":"传统说法认为，这首诗和卫国的州吁有关。公元前719年，州吁杀了哥哥卫桓公，自立为君。为了树立威信、转移国内不满，他联合宋、陈、蔡等国攻打郑国。\n\n这样一场为了一个人的权位而发动的战争，代价却落在无数普通士兵身上。《击鼓》里的「我」，也许就是其中之一。\n\n读历史时，我们常看到君王和战役；读《诗经》时，我们看到的是那个丢了马、回不了家的人。"},"image":"/poems/jigu.png"},"appreciation":{"type":"文学回响","title":"张爱玲眼中「最悲哀的一首诗」","body":"张爱玲在小说《倾城之恋》里，让男主角范柳原念出「死生契阔」这几句，并说这是一首最悲哀的诗。\n\n他的理由是：人在生死离合面前是多么渺小，却偏偏要说「永远」，偏偏要许诺「偕老」，仿佛自己能做主一样。\n\n下次在婚礼上听到「执子之手，与子偕老」，你会知道，这句话的背面，是一个士兵在战场上的叹息。"},"signoff":"**明天见。**愿你身边有可以死生契阔的人。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-22', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安。**执子之手，与子偕老。今天的诗，讲的是这句话说出口之后的故事。","chengyu":{"word":"二三其德","pinyin":"èr sān qí dé","meaning":"心意一会儿这样一会儿那样，反复无常。多指用情不专、言行不一。","examples":["说好一起组队，转头又答应了别人，这么二三其德，下次谁还敢信你？","他对每个女生都说同样的话，这种二三其德的人，还是离远一点吧。"],"note":"语气偏重，带有谴责意味。和「三心二意」相比，它更强调对人对事不忠、违背承诺。","origin":"出自今天的诗《氓》：「士也罔极，二三其德。」同一首诗里还藏着「信誓旦旦」「夙兴夜寐」「总角之交」几个成语，读的时候可以找找看。"},"poem":{"title":"氓（节选）","source":"《诗经 · 卫风》","lines":["{氓|méng}之{蚩蚩|chī chī}，抱布贸丝。匪来贸丝，来即我谋。送子涉{淇|qí}，至于顿丘。匪我{愆|qiān}期，子无良媒。将子无怒，秋以为期。","桑之落矣，其黄而{陨|yǔn}。自我{徂|cú}尔，三岁食贫。淇水{汤汤|shāng shāng}，{渐|jiān}车帷裳。女也不爽，士贰其行。士也罔极，二三其德。","及尔偕老，老使我怨。淇则有岸，{隰|xí}则有{泮|pàn}。总角之宴，言笑晏晏。信誓旦旦，不思其反。反是不思，亦已焉哉！"],"summary":"一个女子回忆自己的婚姻。当年那个男子笑嘻嘻地抱着布来换丝，其实是来求婚的；她送他渡过淇水，约定秋天成亲。婚后她辛苦操劳多年，他却变了心。最后她说：本想和你白头偕老，如今只剩怨恨；你当初信誓旦旦，却从没想过会违背。算了吧，就这样结束吧！","notes":[{"term":"氓","gloss":"外来的男子，指诗中的丈夫。"},{"term":"蚩蚩","gloss":"笑嘻嘻、憨厚的样子。"},{"term":"抱布贸丝","gloss":"拿布来换丝。"},{"term":"来即我谋","gloss":"其实是来找我商量婚事。"},{"term":"愆期","gloss":"拖延婚期。"},{"term":"{将|qiāng}子无怒","gloss":"请你不要生气。"},{"term":"徂尔","gloss":"嫁到你家。"},{"term":"渐车帷裳","gloss":"河水浸湿了车上的布帘。"},{"term":"不爽","gloss":"没有过错。"},{"term":"罔极","gloss":"没有准则，反复无常。"},{"term":"隰则有泮","gloss":"低洼的湿地也有岸。连河水都有边，我的痛苦却没有尽头。"},{"term":"总角","gloss":"童年。古代孩子把头发扎成两个小髻。"}],"history":{"title":"「抱布贸丝」的布，是布还是钱？","body":"诗里那个男子「抱布贸丝」，拿布来换丝。可「布」到底是什么，学者有两种看法。\n\n一种说就是布匹，反映当时以物易物的交易方式。另一种说是「布币」，一种形状像铲子的青铜钱币，春秋时期已经在中原流通。\n\n不管哪种说法，这四个字都让我们看到春秋时期卫国的市井生活：淇水边有集市，有人做买卖，也有人借着做买卖，偷偷去见心上人。"},"image":"/poems/meng.png"},"appreciation":{"type":"古代社会","title":"「七出」与「三不去」","body":"《氓》的女主角最终被抛弃。在古代，丈夫可以用「七出」休妻，例如不孝顺公婆、没有生儿子、多话、偷盗等等，记载于《大戴礼记》。\n\n但同时也有「三不去」保护妻子：无家可归的不能休，为公婆守过丧的不能休，「前贫贱后富贵」的不能休。\n\n《氓》里的女子陪丈夫「三岁食贫」，按后来的规矩，正属于不该被抛弃的人。可在她的时代，她只能说一句：「亦已焉哉！」"},"signoff":"**明天见。**愿你遇见的人，都信守诺言。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-23', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安。**夙兴夜寐，又是一个早起的日子。今天的诗问了一个很尖锐的问题：凭什么？","chengyu":{"word":"尸位素餐","pinyin":"shī wèi sù cān","meaning":"占着职位却不做事，白白领着俸禄吃饭。","examples":["开会全程滑手机，报告全靠组员，这种尸位素餐的组长谁受得了。","既然当了班长，就别尸位素餐，大家有事总要有人出面。"],"note":"批评性很强，多用于指责在其位不谋其事的人。用在朋友身上要注意语气。","origin":"「素餐」出自今天的诗《伐檀》：「彼君子兮，不素餐兮！」「尸位」出自《尚书》。两者合起来，就成了这个成语。"},"poem":{"title":"伐檀","source":"《诗经 · 魏风》","lines":["{坎坎|kǎn kǎn}伐檀兮，置之河之干兮，河水清且涟{猗|yī}。不{稼|jià}不{穑|sè}，胡取禾三百{廛|chán}兮？不狩不猎，胡瞻尔庭有{县|xuán}{貆|huán}兮？彼君子兮，不素餐兮！","坎坎伐辐兮，置之河之侧兮，河水清且直猗。不稼不穑，胡取禾三百亿兮？不狩不猎，胡瞻尔庭有县特兮？彼君子兮，不素食兮！","坎坎伐轮兮，置之河之{漘|chún}兮，河水清且沦猗。不稼不穑，胡取禾三百{囷|qūn}兮？不狩不猎，胡瞻尔庭有县{鹑|chún}兮？彼君子兮，不素{飧|sūn}兮！"],"summary":"一群伐木工在河边砍檀树，叮叮当当，河水清清。他们忍不住问：你们这些老爷，不种也不收，凭什么拿走那么多粮食？不去打猎，凭什么院子里挂满了兽肉？最后一句用反话收尾：那些「君子」啊，可真不是白吃饭的！","notes":[{"term":"坎坎","gloss":"伐木的声音。"},{"term":"干、侧、漘","gloss":"都是河岸。"},{"term":"涟猗","gloss":"水面起波纹。「猗」是语气词，同「兮」。"},{"term":"稼、穑","gloss":"播种叫稼，收割叫穑。"},{"term":"三百廛","gloss":"三百束，极言其多。「亿」「囷」也都是形容粮食多。"},{"term":"县貆","gloss":"挂着的小貉。「县」通「悬」。"},{"term":"素餐","gloss":"白吃饭，不劳而食。"}],"technique":"最后一句「彼君子兮，不素餐兮」是**反语**：表面上说老爷们不白吃饭，实际是说他们全都在白吃饭。用反话收尾，比直接骂更辛辣。","history":{"title":"此「魏」非彼「魏」","body":"看到「魏风」，很多人会想到战国七雄的魏国。其实这里的魏，是更早的一个小国。\n\n这个魏国是春秋初年的姬姓诸侯国，在今天山西芮城一带。公元前661年，它被晋献公所灭，土地封给了大夫毕万。几百年后，毕万的后代建立了战国时期的魏国。\n\n所以《魏风》是一个早已消失的小国留下的歌。国家亡了，伐木工的质问却留了下来。"},"image":"/poems/fatan.png"},"appreciation":{"type":"字词探源","title":"「尸」和「素」","body":"「尸位」的「尸」，不是尸体。古代祭祀时，会让一个人扮作被祭的祖先，坐在神位上接受祭拜，这个人就叫「尸」。他只需要坐着不动，什么都不用做。\n\n「素」的本义是没有染色的白绢，引申为白、空。「素餐」就是空吃饭，「素来」是一向如此，「素颜」是不施脂粉。\n\n两个字合在一起，正好画出一个人：坐在位子上，什么也不做，白白吃饭。"},"signoff":"**明天见。**今天也认真做事，别让自己尸位素餐。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-24', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安。**昨天骂的是「尸位素餐」的老爷，今天的诗更直接，把他们骂成了一只大老鼠。","chengyu":{"word":"爰得我所","pinyin":"yuán dé wǒ suǒ","meaning":"终于找到了属于自己的地方。形容找到理想的安身之处，或适合自己的位置。","examples":["换了三个 CCA，最后在辩论队里爰得我所。","这间小咖啡馆安静又便宜，复习的时候总算爰得我所。"],"note":"{爰|yuán}是「于是、在那里」。语气很书面，用在日常里有一种郑重其事的幽默感。","origin":"出自今天的诗《硕鼠》：「乐土乐土，爰得我所。」"},"poem":{"title":"硕鼠","source":"《诗经 · 魏风》","lines":["硕鼠硕鼠，无食我黍！三岁{贯|guàn}女，莫我肯顾。{逝|shì}将去女，适彼乐土。乐土乐土，爰得我所。","硕鼠硕鼠，无食我麦！三岁贯女，莫我肯德。逝将去女，适彼乐国。乐国乐国，爰得我直。","硕鼠硕鼠，无食我苗！三岁贯女，莫我肯劳。逝将去女，适彼乐郊。乐郊乐郊，谁之永{号|háo}？"],"summary":"大老鼠啊大老鼠，别再吃我的黍子、麦子、禾苗！我侍奉你这么多年，你却从不顾念我。我发誓要离开你，去那片快乐的土地，在那里找到我的安身之所，再也不必长声哀叹。","notes":[{"term":"硕鼠","gloss":"大老鼠，比喻剥削人民的统治者。"},{"term":"三岁","gloss":"多年，不一定是三年。"},{"term":"贯女","gloss":"侍奉你。「女」通「汝」。"},{"term":"莫我肯顾","gloss":"不肯顾念我。"},{"term":"逝","gloss":"通「誓」，发誓。"},{"term":"适","gloss":"往，去。"},{"term":"莫我肯德","gloss":"不肯对我施恩。"},{"term":"爰得我直","gloss":"在那里得到我应有的公道。「直」一说通「值」。"},{"term":"谁之永号","gloss":"谁还会长声哀叹呢？"}],"history":{"title":"从「硕鼠」到「初税亩」","body":"《硕鼠》的愤怒，来自沉重的负担。西周实行井田制，农民除了耕种自己的田，还要耕种公田，收成归贵族。\n\n到了春秋，这套制度渐渐崩坏。公元前594年，鲁国实行「初税亩」，不论公田私田，一律按田亩收税。这是中国古代土地制度的一个转折点，承认了私田的存在，也意味着赋税的方式变了。\n\n制度在变，可被盘剥的感觉一直都在。所以两千多年来，「硕鼠」一直是贪官的代称。"},"image":"/poems/shuoshu.png"},"appreciation":{"type":"古今对照","title":"乐土、桃花源与乌托邦","body":"《硕鼠》里的「乐土」，是中国文学里最早的理想国之一。\n\n一千多年后，东晋的陶渊明写了《桃花源记》，那里没有赋税，人人安居乐业。1516 年，英国的托马斯 · 莫尔写了《乌托邦》，描绘一个公平的理想社会。\n\n不同时代、不同国家的人，都在想象同一个地方：一个可以「爰得我所」的地方。你心中的乐土又是什么样子呢？"},"signoff":"**周末愉快。**愿你也早日爰得我所。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-25', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安，周日。**周日的早晨适合慢一点。今天的诗，是一个人站在废墟前的叹息。","chengyu":{"word":"黍离之悲","pinyin":"shǔ lí zhī bēi","meaning":"看到故国宫殿成为一片庄稼地而产生的悲痛。指对国家衰亡、往昔繁华不再的感伤。","examples":["回到小时候住的旧组屋区，那里已经拆成一片空地，心里竟有一点黍离之悲。","读到圆明园的历史，很难不生出黍离之悲。"],"note":"本义很沉重，指亡国之痛。现代也可以稍稍夸张地用来形容对故地、旧物消逝的感伤，带一点书卷气。","origin":"出自今天的诗《黍离》。后人用「黍离」代指亡国之痛，「黍离之悲」便成了成语。"},"poem":{"title":"黍离","source":"《诗经 · 王风》","lines":["彼{黍|shǔ}离离，彼{稷|jì}之苗。行迈{靡靡|mǐ mǐ}，中心摇摇。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？","彼黍离离，彼稷之穗。行迈靡靡，中心如醉。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？","彼黍离离，彼稷之实。行迈靡靡，中心如{噎|yē}。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？"],"summary":"那里的黍子长得茂盛，稷从幼苗长到抽穗、结实。我慢慢走着，心里越来越沉，从不安到恍惚，最后像被噎住一样。懂我的人知道我在忧伤；不懂我的人，还以为我在寻找什么。苍天啊，这一切是谁造成的？","notes":[{"term":"黍、稷","gloss":"两种谷物。黍是黄米，稷一说是高粱，一说是小米。"},{"term":"离离","gloss":"茂盛、成行的样子。"},{"term":"行迈靡靡","gloss":"走得很慢。"},{"term":"摇摇","gloss":"心神不安。"},{"term":"如噎","gloss":"像被噎住，悲痛到喘不过气。"},{"term":"此何人哉","gloss":"这是什么人造成的？"}],"technique":"三章里，稷从「苗」到「穗」到「实」，诗人的心从「摇摇」到「如醉」到「如噎」。**景物在生长，悲伤也在加深**。庄稼越茂盛，越显出昔日宫殿的荒凉。","history":{"title":"西周的终点","body":"公元前771年，犬戎攻破西周都城镐京，周幽王被杀。第二年，周平王把都城东迁到洛邑，历史进入东周。\n\n《毛诗序》说，东周的一位大夫出差经过旧都，看到昔日的宗庙宫殿，已经全部变成了黍稷田，徘徊不忍离去，于是写下这首诗。\n\n「王风」的「王」，指的就是东周王室所在的洛邑一带。一个王朝的结束，就藏在一片庄稼地里。"},"image":"/poems/shuli.png"},"appreciation":{"type":"词人共鸣","title":"姜夔走过扬州","body":"一千九百多年后，南宋词人姜夔经过扬州。那里刚经历金兵南侵，昔日繁华的都会一片荒凉。他写下了《扬州慢》。\n\n词前的小序里提到，他的前辈千岩老人读了这首词，说它「有黍离之悲」。\n\n跨越近两千年，一个南宋文人站在扬州的废墟前，心情和那位周朝大夫一模一样。这就是「黍离之悲」这个词的分量。"},"signoff":"**明天见。**知我者，谓我心忧。愿你身边有懂你的人。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-26', '2026-10-15', '诗经 · 风雅之始', $json${"greeting":"**早安，这是《诗经》周的最后一天。**昔我往矣，还记得十二天前，从《关雎》开始的那个早上吗？","chengyu":{"word":"雨雪霏霏","pinyin":"yù xuě fēi fēi","meaning":"雪下得又大又密的样子。常和「杨柳依依」一起用，写今昔对比、物是人非的感慨。","examples":["那年冬天在北京，雨雪霏霏，我第一次见到真正的雪。","出发时还是杨柳依依的春天，回来已经雨雪霏霏，一转眼就过了一年。"],"note":"这里的{雨|yù}读第四声，是动词「落下」。「雨雪」就是下雪，不是下雨又下雪。","origin":"出自今天的诗《采薇》：「昔我往矣，杨柳依依。今我来思，雨雪霏霏。」"},"poem":{"title":"采薇（节选）","source":"《诗经 · 小雅》","lines":["采{薇|wēi}采薇，薇亦作止。曰归曰归，岁亦{莫|mù}止。{靡|mǐ}室靡家，{猃狁|xiǎn yǔn}之故。不{遑|huáng}启居，猃狁之故。","昔我往矣，杨柳依依。今我来思，{雨|yù}雪霏霏。行道迟迟，载渴载饥。我心伤悲，莫知我哀！"],"summary":"一个戍边的士兵，采着野豌豆苗，嘴里念着回家、回家，一年却又到了尽头。没有家，不得安歇，都是因为和猃狁的战争。终于踏上归途时，他想起出发那天，杨柳轻轻摇曳；如今回来，大雪纷飞。路走得慢，又渴又饿，满心悲伤，却没有人知道。","notes":[{"term":"薇","gloss":"野豌豆苗，可以吃。"},{"term":"作","gloss":"长出来。"},{"term":"止","gloss":"句末语气词。"},{"term":"岁亦莫止","gloss":"一年又到了年底。「莫」通「暮」。"},{"term":"猃狁","gloss":"周代北方的一个民族。"},{"term":"不遑启居","gloss":"没有时间休息。"},{"term":"依依","gloss":"柳枝轻柔摇曳，好像依依不舍。"},{"term":"思","gloss":"句末语气词。"},{"term":"霏霏","gloss":"雪花纷飞。"}],"technique":"「杨柳依依」是乐景，写的却是离别；「雨雪霏霏」是哀景，写的却是归来。王夫之说这是「**以乐景写哀，以哀景写乐，一倍增其哀乐**」。短短十六个字，就是一整段人生。","history":{"title":"周王朝的北方边境","body":"猃狁是活动在周朝北方的游牧民族，常常南下侵扰。西周后期，周宣王曾派大将尹吉甫北伐猃狁，《诗经 · 小雅 · 六月》就记录了这场战争。\n\n《采薇》里的士兵，就是守在这条边境线上的无数普通人之一。他们离开家乡，一走就是好几年。\n\n读到这里，你也许会想起《击鼓》里那个回不了家的士兵。从卫国到北方，从春天到冬天，《诗经》替这些没有名字的人，留下了他们的声音。"},"image":"/poems/caiwei.png"},"appreciation":{"type":"名士佳话","title":"谢家子弟的选择","body":"《世说新语》里有个故事。东晋的谢安有一天问家中子弟：「《诗经》里哪一句最好？」\n\n侄子谢玄回答，就是「昔我往矣，杨柳依依。今我来思，雨雪霏霏」。\n\n谢安自己选的是《大雅》里一句讲治国的话，但谢玄的回答流传得更广。一千六百多年来，许多读者都同意他：这是《诗经》里最美的句子。\n\n这十二天读下来，你心中最好的一句又是哪一句呢？"},"signoff":"**《诗经》周到这里结束。**明天起，我们离开北方的黄河，往南走，去听屈原的《楚辞》。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();


-- Week 1 now starts on Thu 15 Oct. Remove the earlier test dates so the archive
-- doesn't show 关雎 twice and no stray intro goes out.
delete from issues where date = '2026-10-14';
delete from weeks where week_start in ('2026-10-14', '2026-10-19');
